python3 - <<'EOF'
import re,zlib
d=open('requirements.pdf','rb').read()
out=[]
for m in re.finditer(rb'stream\r?\n(.*?)\r?\nendstream',d,re.S):
    s=m.group(1)
    try: s=zlib.decompress(s)
    except Exception: continue
    t=re.findall(rb'\[(.*?)\]\s*TJ|\((.*?)\)\s*Tj',s,re.S)
    if t:
        line=[]
        for a,b in t:
            if a: line.append(b''.join(re.findall(rb'\((.*?)(?<!\\)\)',a)))
            else: line.append(b)
        out.append(b'\n'.join(line).decode('latin-1'))
print('\n---\n'.join(out)[:20000])
EOF

